import { pairedDelta, pairedCi, pairedRho, type OpponentPairs, type PairedStats }
  from "./stats";                                   // S07.T02 owns these

export const BLOCK_PAIRS          = 500;   // paired games per opponent per block
export const MAX_BLOCKS           = 4;     // 4 × 12 × 500 = 24,000 pairs
export const MAX_BLOCKS_HARD      = 8;     // ceiling when lowRhoPolicy = "extend"
export const MAX_SURVIVORS        = 4;     // Bonferroni cost cap (BR-S07.T03-05)
export const ALPHA                = 0.05;  // two-sided, before the Bonferroni split
export const FUTILITY_K_SE        = 2;     // stop when Δ + FUTILITY_K_SE·SE < 0 after block 1
export const RHO_FOR_FULL_POWER   = 0.4;   // the ρ at which 24,000 pairs give 80 % power
export const TARGET_DELTA         = 0.01;  // δ = 1 point, the effect the budget is sized for

export type ConfirmOutcome    = "confirmed" | "rejected";
export type ConfirmStopReason = "ci_excludes_zero" | "futility" | "blocks_exhausted" | "cancelled";
export type LowRhoPolicy      = "extend" | "report";

export interface ConfirmOpts {
  jobId: number;
  iteration: number;
  seed0: number;
  alpha?: number;                 // default ALPHA
  blockPairs?: number;            // default BLOCK_PAIRS
  maxBlocks?: number;             // default MAX_BLOCKS
  lowRhoPolicy?: LowRhoPolicy;    // default "report" (BR-S07.T03-07)
  bot: string;                    // the cheap bot; the planner (S06.T03)
  opponentBot: string;
}

export interface ReferenceBlock {
  block: number;                                    // 1-based
  seedBases: ReadonlyMap<string, number>;
  gamesByOpponent: ReadonlyMap<string, GameRow[]>;
  engineBuild: string;
  rulesSnapshot: string;
}

export interface BlockRow {                         // one row per block, kept for the audit trail
  block: number; n: number; delta: number; se: number;
  ciLow: number; ciHigh: number; droppedPairs: number;
}

export interface ConfirmResult {
  idx: number;                    // the candidate's index inside the iteration
  move: Move;
  outcome: ConfirmOutcome;
  stopReason: ConfirmStopReason;
  blocksRun: number;              // the interval below is computed from THESE blocks (BR-S07.T03-03)
  n: number;                      // Σ surviving pairs over blocksRun
  delta: number;                  // Δ in win-rate units; ×100 for points
  se: number;
  ciLow: number; ciHigh: number;  // two-sided at z = bonferroniZ(alpha, m)
  z: number;
  alphaSpent: number;             // α / m — the Bonferroni share, not a spending schedule
  survivors: number;              // m, for reproducing z
  rho: number;                    // measured from block 1 (BR-S07.T03-06)
  powerAtMeasuredRho: number;     // power for δ = TARGET_DELTA at (rho, n, z)
  tieFraction: number;
  droppedPairs: number;
  blocks: BlockRow[];
  byOpponent: PairedStats["byOpponent"];
}

/** RN-46 salt for confirmation; disjoint from screen and holdout (BR-S07.T02-04). */
export function confirmSeedBase(
  seed0: number, jobId: number, iteration: number, block: number, opponentDeckId: string): number;

export function buildConfirmPairings(
  db: Db, list: readonly DeckLine[], opponents: readonly SuiteOpponent[],
  seedBases: ReadonlyMap<string, number>, opts: ConfirmOpts): Pairing[];

/** z = Φ⁻¹(1 − α/(2m)). m = 1 gives 1.960; m = 4 gives 2.498 (BR-S07.T03-02). */
export function bonferroniZ(alpha: number, m: number): number;

/** Power for a paired difference δ at correlation ρ over n pairs at level z, σ² = 0.25. */
export function powerAtMeasuredRho(rho: number, n: number, z: number, delta?: number): number;

/** The stop decision after a block. `null` means continue. */
export function shouldStop(stats: PairedStats, block: number, z: number): ConfirmStopReason | null;

export function selectSurvivors(results: readonly ScreenResult[], max?: number):
  { survivors: ScreenResult[]; budgetCapped: ScreenResult[] };

/** Drives the block loop; `runBlock` is injected so the module itself spawns nothing (BR-S07.T03-09). */
export function confirm(
  survivors: readonly ScreenResult[],
  runBlock: (block: number, lists: readonly DeckLine[][]) =>
    Promise<{ reference: ReferenceBlock; arms: ReadonlyMap<string, GameRow[]>[] }>,
  opponents: readonly SuiteOpponent[],
  opts: ConfirmOpts,
): Promise<ConfirmResult[]>;

export class ReferenceMismatch extends Error { readonly field: "block" | "seed_base" | "engine_build" | "rules_snapshot" }

import { pairedDelta, pairedCi, type PairedStats } from "./stats";   // S07.T02
import type { ConfirmResult } from "./confirm";                      // S07.T03

export const MIN_DELTA = 0.005;   // 0.5 percentage points — the practical condition (RN-84)

export type CandidateDecision = "screened_out" | "rejected" | "confirmed" | "accepted";

export interface AcceptOpts {
  jobId: number;
  iteration: number;
  seed0: number;
  deckId: number;                 // the user deck the versions belong to
  parentVersionNo: number;        // the version the swap is applied to
  strongBot: string;              // the rollout bot (S06.T05), used for the holdout only
  opponentBot: string;
  holdoutPairs?: number;          // default HOLDOUT_PAIRS (500 per opponent)
  apiBaseUrl: string;             // the api the version is created through (BR-S07.T04-06)
}

export interface HoldoutResult {
  seedSet: string;                // the salt, stored verbatim (BR-S07.T04-02)
  bot: string;
  n: number;
  delta: number; se: number; ciLow: number; ciHigh: number; rho: number;
  belowConfirm: boolean;          // derived (BR-S07.T04-04)
  belowZero: boolean;
}

export interface AcceptResult {
  idx: number;
  decision: CandidateDecision;
  reportedDelta: number | null;   // the HOLDOUT delta when accepted, else null
  holdout: HoldoutResult | null;
  deckVersionId: number | null;
  note: string | null;
}

/** The two conditions of RN-84, on the confirmation interval only. Never sees the holdout. */
export function isAccepted(c: Pick<ConfirmResult, "ciLow" | "delta">, minDelta?: number): boolean;

/** RN-46 salt for the holdout; disjoint from screen and confirm (BR-S07.T04-02). */
export function holdoutSeedSet(jobId: number, iteration: number): string;           // 'optimize:41:holdout:2'
export function holdoutSeedBase(seed0: number, jobId: number, iteration: number, opponentDeckId: string): number;

export function buildHoldoutPairings(
  db: Db, list: readonly DeckLine[], opponents: readonly SuiteOpponent[],
  seedBases: ReadonlyMap<string, number>, opts: AcceptOpts): Pairing[];

/** Paired holdout measurement of the swapped list against the pre-swap list (BR-S07.T04-10). */
export function measureHoldout(
  swapped: ReadonlyMap<string, GameRow[]>, reference: ReadonlyMap<string, GameRow[]>,
  opponents: readonly SuiteOpponent[], confirmDelta: number, opts: AcceptOpts): HoldoutResult;

/** POSTs to the api; the worker never writes user_deck_versions itself (BR-S07.T04-06). */
export function createAcceptedVersion(
  opts: AcceptOpts, list: readonly DeckLine[], move: Move, holdout: HoldoutResult): Promise<number>;

/**
 * Decides, then (only when accepted) measures the holdout, then records.
 * `decision` is computed from `confirmed` alone, before `runHoldout` is called (BR-S07.T04-01).
 */
export function accept(
  confirmed: readonly ConfirmResult[],
  runHoldout: (lists: readonly DeckLine[][], seedBases: ReadonlyMap<string, number>) =>
    Promise<{ swapped: ReadonlyMap<string, GameRow[]>; reference: ReadonlyMap<string, GameRow[]> }>,
  opponents: readonly SuiteOpponent[],
  opts: AcceptOpts,
): Promise<AcceptResult[]>;

/** Insert-only; one row per considered candidate, including screened-out ones (BR-S07.T04-05). */
export function writeCandidates(db: Db, jobId: number, rows: readonly OptimizerCandidateRow[]): { inserted: number };

export class UnknownBot extends Error { readonly name_: string }

export interface OptimizeProgress {
  iteration: number;              // 1-based
  maxIterations: number;
  phase: "propose" | "screen" | "confirm" | "holdout" | "apply" | "final_holdout" | "done";
  candidate: { idx: number; moveDesc: string } | null;   // null outside per-candidate phases
  block: number | null;           // confirmation block in flight
  blocksPlanned: number | null;
  arm: { label: string; done: number; total: number } | null;
  gamesDone: number;
  gamesBudget: number;
  proposed: number; screened: number; survivors: number; confirmed: number; accepted: number;
  elapsedMs: number;
  updatedAt: string;              // ISO-8601 UTC
}

export interface OptimizeResult {
  suiteId: number | null;
  startDeckVersionId: number;
  finalDeckVersionId: number;                 // === start when nothing was accepted
  iterationsRun: number;
  counts: { proposed: number; screened: number; survivors: number;
            confirmed: number; accepted: number; budgetCapped: number };
  acceptedMoves: {
    iteration: number; moveDesc: string;
    confirmDelta: number; confirmCi: [number, number]; blocksRun: number; alphaSpent: number;
    holdoutDelta: number; holdoutCi: [number, number]; holdoutBelowZero: boolean;
    deckVersionId: number;
  }[];
  /** The run's headline: final list vs the starting list, on its own seed set (BR-S07.T05-07). */
  finalHoldout: {
    seedSet: string; bot: string; n: number; rho: number;
    delta: number; se: number; ciLow: number; ciHigh: number; belowZero: boolean;
  } | null;
  stopReason: OptimizeStopReason;
  games: number; seconds: number;
  engineBuild: string; rulesSnapshot: string;
  unmodelledExcluded: { name: string; status: string; copies: number }[];   // RN-81 report
}

export type OptimizeStopReason =
  | "max_iterations" | "no_moves_left" | "no_candidate_passed" | "no_candidate_confirmed"
  | "budget_exhausted" | "time_budget" | "environment_changed" | "cancelled";

export interface ArmResult {
  pairingIdxBase: number;
  gamesByOpponent: ReadonlyMap<string, GameRow[]>;   // in memory; rows may already be dropped
  engineBuild: string;
  fingerprints: ReadonlyMap<string, string>;
  games: number;
}

/** One ptcg-cli invocation for a whole phase-arm, then fold-then-drop (BR-S07.T05-09). */
export function runArm(
  db: Db, job: JobRow, pairings: readonly Pairing[], label: string, params: OptimizeParams,
): Promise<ArmResult>;

export function nextPairingIdx(db: Db, jobId: number): number;
export function resumeFrom(db: Db, jobId: number): number;                 // first unrecorded iteration
export function canAfford(next: readonly Pairing[], spent: number, params: OptimizeParams): boolean;
export function estimateArm(pairings: readonly Pairing[]): number;         // Σ games
export function armBot(phase: OptimizeProgress["phase"], params: OptimizeParams): string;  // BR-S07.T05-02

